; ==================================================================
; MAPPER RUNTIME API
; File: mapper.asm
; Description: Centralized mapper register writes (no scattered inline writes)
; Target mapper: ascii16
; ROM mode: megarom (autoMegaROM=false)
; ==================================================================

; ASCII16 register mapping (MSX Wiki ROM mappers):
;   4000-7FFF <- 6000h (P1/P2 share one 16KB register)
;   8000-BFFF <- 7000h (P3/P4 share one 16KB register)
; Mapper register writes are enabled for this build configuration.

; Mapper registers for active target format
MAPPER_REG_P1       EQU #6000
MAPPER_REG_P2       EQU #6000
MAPPER_REG_P3       EQU #7000
MAPPER_REG_P4       EQU #7000

; ------------------------------------------------------------------
; mapper_runtime_init
; Initializes mapper state variables with deterministic defaults.
; ------------------------------------------------------------------
mapper_runtime_init:
    ; ASCII16 switches 16 KB pages, so P1/P2 and P3/P4 are mirrors.
    ; Do not write P2 separately during boot: it shares register #6000
    ; with P1 and would remap the bank-0 trampoline/header page.
    xor a
    call mapper_set_bank_p1
    ld (mapper_bank_p2_current), a
    ld a, 1
    call mapper_set_bank_p3
    ld (mapper_bank_p4_current), a
    ret

; ------------------------------------------------------------------
; API: mapper_set_bank_pX
; Input: A = bank number
; ------------------------------------------------------------------
mapper_set_bank_p1:
    ; ASCII16 maps #4000-#7FFF as a single 16 KB segment.
    ld (mapper_bank_p1_current), a
    ld (mapper_bank_p2_current), a
    ld (MAPPER_REG_P1), a
    ret

mapper_set_bank_p2:
    jp mapper_set_bank_p1

mapper_set_bank_p3:
    ; ASCII16 maps #8000-#BFFF as a single 16 KB segment.
    ld (mapper_bank_p3_current), a
    ld (mapper_bank_p4_current), a
    ld (MAPPER_REG_P3), a
    ret

mapper_set_bank_p4:
    jp mapper_set_bank_p3

; ------------------------------------------------------------------
; Helpers for deterministic save/restore around far calls.
; ------------------------------------------------------------------
mapper_push_p1:
    ld a, (mapper_bank_p1_current)
    ld (mapper_saved_bank_p1), a
    ret

mapper_pop_p1:
    ld a, (mapper_saved_bank_p1)
    jp mapper_set_bank_p1

mapper_push_p2:
    ld a, (mapper_bank_p2_current)
    ld (mapper_saved_bank), a
    ret

mapper_pop_p2:
    ld a, (mapper_saved_bank)
    jp mapper_set_bank_p2

mapper_push_p3:
    ld a, (mapper_bank_p3_current)
    ld (mapper_saved_bank_p3), a
    ret

mapper_pop_p3:
    ld a, (mapper_saved_bank_p3)
    jp mapper_set_bank_p3

mapper_push_p4:
    ld a, (mapper_bank_p4_current)
    ld (mapper_saved_bank_p4), a
    ret

mapper_pop_p4:
    ld a, (mapper_saved_bank_p4)
    jp mapper_set_bank_p4

; ------------------------------------------------------------------
; Far call helpers (dynamic target address in HL)
; Input:
;   A = target bank number
;   HL = target routine address in selected page window
; Output:
;   Returns after restoring previous bank.
; Preserves:
;   DE across mapper trampoline code. The target routine may still define
;   its own clobbers; callers must save any live registers required by GameFlow.
; ------------------------------------------------------------------
mapper_call_hl_p1:
    ; ASCII16 remaps the full #4000-#7FFF lower page. Execute the
    ; switch/call/restore sequence from RAM so this bank-0 helper is not hidden.
    jp ASCII16_FAR_CALL_P1_RAM

mapper_call_hl_p2:
    jp mapper_call_hl_p1


mapper_call_hl_p3:
    push hl
    push af
    call mapper_push_p3
    pop af
    call mapper_set_bank_p3
    pop hl
    push de
    ld de, .return_p3
    push de
    jp (hl)
.return_p3:
    call mapper_pop_p3
    pop de
    ret

mapper_call_hl_p4:
    push hl
    push af
    call mapper_push_p4
    pop af
    call mapper_set_bank_p4
    pop hl
    push de
    ld de, .return_p4
    push de
    jp (hl)
.return_p4:
    call mapper_pop_p4
    pop de
    ret

; ------------------------------------------------------------------
; ------------------------------------------------------------------
; mapper_call_hl_auto
; Auto-select mapper window from HL target address range:
;   4000-7FFF -> p1 (ASCII16 lower 16 KB page)
;   8000-BFFF -> p3 (ASCII16 upper 16 KB page)
; Input:
;   A = target bank
;   HL = target routine address
; ------------------------------------------------------------------
mapper_call_hl_auto:
    push af
    ld a, h
    cp #80
    jr c, .use_p1
    pop af
    jp mapper_call_hl_p3

.use_p1:
    pop af
    jp mapper_call_hl_p1



