a16ix0:
    db #F5, #3A, (ascii16_irq_saved_bank) & #FF, ((ascii16_irq_saved_bank) >> 8) & #FF, #32, (mapper_bank_p1_current) & #FF, ((mapper_bank_p1_current) >> 8) & #FF, #32, (mapper_bank_p2_current) & #FF, ((mapper_bank_p2_current) >> 8) & #FF, #32, #00, #60, #F1, #C3, (old_htimi_hook) & #FF, ((old_htimi_hook) >> 8) & #FF


; --- Far bank 4 [#6000, window P1] trampolines ---
FAR_BANK_4 EQU 2
; Mapper bank 2 is the ASCII16 runtime segment for packed far bank 4.

SM_ExecuteActions_far:
    ex af, af'
    di
    ld a, FAR_BANK_4
    ld hl, SM_ExecuteActions
    call ASCII16_FAR_CALL_P1_PRESERVE_A_RAM
    ld a, (interrupt_in_progress)
    or a
    jp nz, .SM_ExecuteActions_far_irq_done
    ld a, (mapper_bank_p1_current)
    or a
    jp nz, .SM_ExecuteActions_far_irq_done
    ei
.SM_ExecuteActions_far_irq_done:
    ex af, af'
    ret

