Action_RegenerateHud:
; No params - force a HUD redraw, preserving the caller-visible state
    call a16r4_0_call_for
    ret

; [Action_DecLives stripped - not used]

; [Action_BreakTile stripped - not used]

Action_ReplaceTile:
; Params: TileID(1 byte), Direction(1 byte)
    ld a, (hl)              ; A = replacement tile ID
    inc hl
    ld c, (hl)              ; C = direction (0..7)
    inc hl
    push hl
    call SM_WriteTileRelativeToEntity
    pop hl
    ret

; [Action_ReplaceTileAt stripped - not used]

; [Action_MoveTileArea stripped - not used]

; [Action_ShiftTileArea stripped - not used]

